SELECT id, account_id, txn_type, txn_time, is_flagged, AVG(amount) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS amount_avg_5_prior, LAG(amount, 1) OVER (PARTITION BY account_id ORDER BY txn_time, id) AS prev_amount, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY txn_time, id) AS event_seq FROM transactions WHERE txn_time >= '2025-06-01';
